package cn.zhuatech.kms.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class KnowledgePublicationGovernanceServiceTest{private final KnowledgePublicationGovernanceService service=new KnowledgePublicationGovernanceService();@Test void publishesGovernedKnowledge(){var r=service.assess(new KnowledgePublicationGovernanceService.Request("K1","A","R",true,true,true,true,95,true,true));assertThat(r.decision()).isEqualTo(KnowledgePublicationGovernanceService.Decision.PUBLISH);}@Test void blocksEditorialAndAccessFailures(){var r=service.assess(new KnowledgePublicationGovernanceService.Request("K2","A","A",false,true,false,false,95,true,true));assertThat(r.blockers()).hasSize(4);}@Test void reviewsLifecycleGaps(){var r=service.assess(new KnowledgePublicationGovernanceService.Request("K3","A","R",true,false,false,true,60,false,false));assertThat(r.actions()).hasSize(3);}}
